Method.Implementation:
Try {
	Set tStatus = $$$OK
	Set pObject = $$$NULLOREF
	If '$IsObject(pStream) {
		Set tFilename = pStream
		Set pStream = ##class(%IO.FileStream).%New()
		Do pStream.Open(tFilename,,pTimeout,"UTF-8", .tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tObjectName = $parameter($this,"OBJECTNAME")
	Set tObject = $classmethod(tObjectName,"%New")
	If '$IsObject(tObject) {
		Set tStatus = $$$ERROR($$$CannotCreateObject,tObjectName)
		Quit
	}
	Set tObject.%Source = pStream.Name
	Set tGetTopFields = $parameter(tObject,"INCLUDETOPFIELDS")
	If pStream.AtEnd && (""=pLookAhead) {
		Set tStatus = $$$ERROR($$$EnsRecordMapErrStreamAtEnd, pStream.Name)
		Quit
	}
	Set pStream.CharEncoding = "UTF-8"

	#; Parse incoming stream
	Set tStatus = ..GetRecord(pStream, tObject, tGetTopFields, pTimeout, .pLookAhead, pLabelFound)
	If $$$ISERR(tStatus) Quit
}
Catch ex {
	Set tStatus = ex.AsStatus()
}
If $$$ISERR(tStatus) { Set pObject = $$$NULLOREF }
Else { Set pObject = tObject }
Quit tStatus

Try {
	Set tStatus = $$$OK
	If '$IsObject(pStream) {
		Set tFilename = pStream
		Set pStream = ##class(%IO.FileStream).%New()
		Do pStream.Open(tFilename,"WAE",,"UTF-8", .tStatus)
		If $$$ISERR(tStatus) Quit
	}
	Set tHasTopFields = $parameter(pObject,"INCLUDETOPFIELDS")
	Set pStream.CharEncoding = "UTF-8"

	Set tStatus = ..PutRecord(pStream, pObject, tHasTopFields, .pPadArray)
	If $$$ISERR(tStatus) Quit
	If pFlush Do pStream.Flush(.tStatus)
	If $$$ISERR(tStatus) Quit
}
Catch ex {
	Set tStatus = ex.AsStatus()
}
Quit tStatus

Set tStatus = $$$OK
If pLabelFound { Set tRecLabel = "" } 
Else { Set tRecLabel = "" } 
Set tStatus = ..chunkRecord(pStream, .tRecordData, .tCharCount, "", pTimeout, $char(13,10), tRecLabel, .pLookAhead, "", 0)
If $$$ISERR(tStatus) Quit tStatus
Set tMaxLocal = $$$MaxLocalLength
Set tRecordData("charcount") = +$get(tCharCount)
Set tCurrChunk = 1
Set tTopPiece = 1
Set tCurrSep = 1
Set tStrings = 1
Set tCurrString = ""
Set tSeps = $listbuild($char(44))
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Else {
	Set tCurrString = tRecordData(tCurrChunk)
	Set tCurrPiece = 1
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.RecTypeCLCC = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.CARCSequenceNumberCLC = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.PayerResponsibilitySequenceNumbercode = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.OtherPayerID = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.CARCCode = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.GroupCode = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.CARCDollars = tCurrString
}
If '$data(tRecordData(tCurrChunk, "block")) {
	Set tCurrString = $piece(tRecordData(tCurrChunk), $char(44), tTopPiece)
}
Do ..checkMerge(.tCurrChunk, .tRecordData, .tCurrString, $char(44), .tTopPiece)
If pGetTopFields {
	Set pObject.CARCUnits = tCurrString
}
Quit tStatus
